<?php
namespace App\Domain\GhostEvents\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
class GhostEvent extends Model { protected $fillable=['slug','season_id','tournament_id','name','description','environment_id','course_id','course_version','weather_preset_id','weather_seed','physics_version','starts_at','ends_at','benchmark_type','scoring_type','max_attempts','max_visible_ghosts','reward_configuration_json','enabled']; protected function casts():array{return ['starts_at'=>'datetime','ends_at'=>'datetime','enabled'=>'boolean','reward_configuration_json'=>'array'];} public function benchmarks():HasMany{return $this->hasMany(GhostEventBenchmark::class);} public function attempts():HasMany{return $this->hasMany(GhostEventAttempt::class);} }
